// port of pickRequestJSON (gemini_openai-responses_response.go)
fn pick_request_json<'a>(
    original: Option<&'a Value>,
    request: Option<&'a Value>,
) -> Option<&'a Value> {
    original.or(request)
}

// port of unwrapRequestRoot (gemini_openai-responses_response.go)
fn unwrap_request_root(root: &Value) -> &Value {
    match root.get("request") {
        Some(req)
            if req.get("model").is_some()
                || req.get("input").is_some()
                || req.get("instructions").is_some() =>
        {
            req
        }
        _ => root,
    }
}

// port of unwrapGeminiResponseRoot (gemini_openai-responses_response.go)
fn unwrap_gemini_response_root(root: &Value) -> &Value {
    match root.get("response") {
        Some(resp)
            if resp.get("candidates").is_some()
                || resp.get("responseId").is_some()
                || resp.get("usageMetadata").is_some() =>
        {
            resp
        }
        _ => root,
    }
}

// port of emitEvent (gemini_openai-responses_response.go)
fn emit_event(event: &str, payload: &Value) -> String {
    format!("event: {event}\ndata: {payload}\n\n")
}

// port of hasEffectiveGoogleSearchTool (gemini_openai-responses_response.go)
fn has_effective_google_search_tool(raw: &Value) -> bool {
    if gs(raw, "requestType") == "web_search" {
        return true;
    }
    for path in ["request.tools", "tools"] {
        if let Some(Value::Array(tools)) = gpath(raw, path) {
            if tools.iter().any(|t| t.get("googleSearch").is_some()) {
                return true;
            }
        }
    }
    false
}

// port of isUpstreamGeminiRequest (gemini_openai-responses_response.go)
fn is_upstream_gemini_request(raw: &Value) -> bool {
    raw.get("requestType").is_some()
        || raw.get("contents").is_some()
        || gexists(raw, "request.contents")
}

// port of determineWebSearchStreamMode (gemini_openai-responses_response.go)
fn determine_web_search_stream_mode(
    model_name: &str,
    request_model_name: &str,
    original: Option<&Value>,
    request: Option<&Value>,
) -> bool {
    if let Some(orig) = original {
        if !allows_responses_web_search_tool_choice(unwrap_request_root(orig)) {
            return false;
        }
    }
    if let Some(req) = request {
        let root = unwrap_request_root(req);
        if root.get("tool_choice").is_some() && !allows_responses_web_search_tool_choice(root) {
            return false;
        }
        if is_upstream_gemini_request(req) || has_effective_google_search_tool(req) {
            return has_effective_google_search_tool(req);
        }
    }
    if let Some(req_json) = pick_request_json(original, request) {
        let root = unwrap_request_root(req_json);
        return has_responses_web_search_tool(root)
            && allows_responses_web_search_tool_choice(root)
            && (model_supports_web_search(model_name)
                || model_supports_web_search(request_model_name));
    }
    false
}

/// Request fields echoed onto `response.completed` / the non-stream response.
fn echo_request_fields(target: &mut Value, prefix: &str, req: &Value) {
    let path = |k: &str| {
        if prefix.is_empty() {
            k.to_string()
        } else {
            format!("{prefix}.{k}")
        }
    };
    let mut put = |k: &str, v: Value| set_path(target, &path(k), v);
    if let Some(v) = req.get("instructions") {
        put("instructions", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("max_output_tokens") {
        put("max_output_tokens", json!(gint(Some(v))));
    }
    if let Some(v) = req.get("max_tool_calls") {
        put("max_tool_calls", json!(gint(Some(v))));
    }
    if let Some(v) = req.get("model") {
        put("model", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("parallel_tool_calls") {
        put("parallel_tool_calls", json!(gbool(Some(v))));
    }
    if let Some(v) = req.get("previous_response_id") {
        put("previous_response_id", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("prompt_cache_key") {
        put("prompt_cache_key", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("reasoning") {
        put("reasoning", v.clone());
    }
    if let Some(v) = req.get("safety_identifier") {
        put("safety_identifier", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("service_tier") {
        put("service_tier", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("store") {
        put("store", json!(gbool(Some(v))));
    }
    if let Some(v) = req.get("temperature") {
        put("temperature", float_value(gfloat(Some(v))));
    }
    if let Some(v) = req.get("text") {
        put("text", v.clone());
    }
    if let Some(v) = req.get("tool_choice") {
        put("tool_choice", v.clone());
    }
    if let Some(v) = req.get("tools") {
        put("tools", v.clone());
    }
    if let Some(v) = req.get("top_logprobs") {
        put("top_logprobs", json!(gint(Some(v))));
    }
    if let Some(v) = req.get("top_p") {
        put("top_p", float_value(gfloat(Some(v))));
    }
    if let Some(v) = req.get("truncation") {
        put("truncation", json!(gstr(Some(v))));
    }
    if let Some(v) = req.get("user") {
        put("user", v.clone());
    }
    if let Some(v) = req.get("metadata") {
        put("metadata", v.clone());
    }
}

struct CompletedMessage {
    id: String,
    text: String,
    annotations: Vec<Value>,
}

struct CompletedReasoning {
    id: String,
    signature: String,
    text: String,
}

struct DetachedReasoning {
    id: String,
    signature: String,
}

/// Per-stream state of `ConvertGeminiResponseToOpenAIResponses`
/// (`geminiToResponsesState` plus the request context the Go function
/// receives on every call).
pub struct StreamTranslator {
    original: Option<Value>,
    request: Option<Value>,
    model_name: String,

    seq: i64,
    response_id: String,
    created_at: i64,
    started: bool,
    completed: bool,

    msg_opened: bool,
    msg_closed: bool,
    msg_index: i64,
    current_msg_id: String,
    item_text_buf: String,

    reasoning_opened: bool,
    reasoning_index: i64,
    reasoning_item_id: String,
    reasoning_enc: String,
    reasoning_direction: String,
    reasoning_target_kind: String,
    reasoning_buf: String,
    reasoning_pending_deltas: Vec<String>,
    reasoning_closed: bool,
    pending_reasoning_signature: String,
    detached_reasoning: HashMap<i64, DetachedReasoning>,
    completed_messages: BTreeMap<i64, CompletedMessage>,
    completed_reasoning: HashMap<i64, CompletedReasoning>,
    seen_reasoning_signatures: HashSet<String>,
    last_semantic_kind: String,
    hidden_text_signatures: HashMap<String, Vec<String>>,

    next_index: i64,
    func_args_buf: BTreeMap<i64, String>,
    func_input_buf: HashMap<i64, String>,
    func_custom: HashMap<i64, bool>,
    func_names: HashMap<i64, String>,
    func_namespaces: HashMap<i64, String>,
    func_call_ids: HashMap<i64, String>,
    func_done: HashSet<i64>,
    sanitized_name_map: HashMap<String, String>,
    tool_identity_map: HashMap<String, ResponsesToolIdentity>,

    web_search_stream_mode: bool,
    web_search_opened: bool,
    web_search_done: bool,
    web_search_index: i64,
    web_search_item_id: String,
    web_search_query: String,
    web_search_queries: Vec<String>,
    web_search_sources: Vec<Value>,
    web_search_buffered_deltas: Vec<String>,
    web_search_buffered_parts: Vec<(i64, String)>,
    raw_grounding_metadata: Option<Value>,
    part_mappings: Vec<GeminiPartMapping>,
    current_logical_part_index: i64,
    current_part_kind: String,
    has_seen_first_part: bool,
    text_part_run_active: bool,
    current_msg_rune_offset: i64,
    emitted_annotation_count: HashMap<i64, usize>,

    out: Vec<String>,
}

impl StreamTranslator {
    /// `original_request` is the client's ORIGINAL Responses body; its `model`
    /// stands in for the executor's model name.
    pub fn new(original_request: &Value) -> Self {
        let model = gs(original_request, "model");
        Self::with_requests(Some(original_request.clone()), None, &model)
    }

    /// Go's full parameter set: `original` / `request` are the
    /// `originalRequestRawJSON` / `requestRawJSON` arguments (None = nil or
    /// invalid), `model_name` the executor's model.
    fn with_requests(original: Option<Value>, request: Option<Value>, model_name: &str) -> Self {
        let req_json = pick_request_json(original.as_ref(), request.as_ref()).cloned();
        StreamTranslator {
            sanitized_name_map: sanitized_tool_name_map(original.as_ref()),
            tool_identity_map: responses_tool_reverse_identity_map(req_json.as_ref()),
            original,
            request,
            model_name: model_name.to_string(),
            seq: 0,
            response_id: String::new(),
            created_at: 0,
            started: false,
            completed: false,
            msg_opened: false,
            msg_closed: false,
            msg_index: 0,
            current_msg_id: String::new(),
            item_text_buf: String::new(),
            reasoning_opened: false,
            reasoning_index: 0,
            reasoning_item_id: String::new(),
            reasoning_enc: String::new(),
            reasoning_direction: String::new(),
            reasoning_target_kind: String::new(),
            reasoning_buf: String::new(),
            reasoning_pending_deltas: Vec::new(),
            reasoning_closed: false,
            pending_reasoning_signature: String::new(),
            detached_reasoning: HashMap::new(),
            completed_messages: BTreeMap::new(),
            completed_reasoning: HashMap::new(),
            seen_reasoning_signatures: HashSet::new(),
            last_semantic_kind: String::new(),
            hidden_text_signatures: HashMap::new(),
            next_index: 0,
            func_args_buf: BTreeMap::new(),
            func_input_buf: HashMap::new(),
            func_custom: HashMap::new(),
            func_names: HashMap::new(),
            func_namespaces: HashMap::new(),
            func_call_ids: HashMap::new(),
            func_done: HashSet::new(),
            web_search_stream_mode: false,
            web_search_opened: false,
            web_search_done: false,
            web_search_index: 0,
            web_search_item_id: String::new(),
            web_search_query: String::new(),
            web_search_queries: Vec::new(),
            web_search_sources: Vec::new(),
            web_search_buffered_deltas: Vec::new(),
            web_search_buffered_parts: Vec::new(),
            raw_grounding_metadata: None,
            part_mappings: Vec::new(),
            current_logical_part_index: 0,
            current_part_kind: String::new(),
            has_seen_first_part: false,
            text_part_run_active: false,
            current_msg_rune_offset: 0,
            emitted_annotation_count: HashMap::new(),
            out: Vec::new(),
        }
    }

    /// One upstream SSE event (`data` is the parsed JSON of its `data:` line).
    pub fn push(&mut self, _event: Option<&str>, data: &Value) -> Vec<String> {
        if self.completed {
            return Vec::new();
        }
        self.convert(data);
        std::mem::take(&mut self.out)
    }

    /// Upstream stream ended: Go's `[DONE]` handling — a started, unfinished
    /// stream is closed as if the last chunk carried `finishReason: STOP`.
    pub fn finish(&mut self) -> Vec<String> {
        if self.completed || !self.started {
            return Vec::new();
        }
        self.convert(&json!({"candidates": [{"finishReason": "STOP"}]}));
        std::mem::take(&mut self.out)
    }

    fn req_json(&self) -> Option<&Value> {
        pick_request_json(self.original.as_ref(), self.request.as_ref())
    }

    fn next_seq(&mut self) -> i64 {
        self.seq += 1;
        self.seq
    }

    fn emit(&mut self, event: &str, payload: Value) {
        self.out.push(emit_event(event, &payload));
    }

    fn reasoning_encrypted_content(&self) -> String {
        if self.reasoning_enc.is_empty() || self.reasoning_direction.is_empty() {
            return self.reasoning_enc.clone();
        }
        encode_gemini_responses_carrier(
            &self.reasoning_enc,
            &self.reasoning_direction,
            &self.reasoning_target_kind,
        )
    }

    fn request_query(&self) -> String {
        match self.req_json() {
            Some(r) => extract_responses_web_search_query(unwrap_request_root(r)),
            None => String::new(),
        }
    }

    // finalizeWebSearch closure
    fn finalize_web_search(&mut self) {
        if !self.web_search_opened || self.web_search_done {
            return;
        }
        if self.web_search_query.is_empty() && !self.web_search_queries.is_empty() {
            self.web_search_query = self.web_search_queries[0].clone();
        }
        if self.web_search_query.is_empty() && self.req_json().is_some() {
            self.web_search_query = self.request_query();
        }
        let seq = self.next_seq();
        let completed = json!({"type":"response.web_search_call.completed","sequence_number":seq,"output_index":self.web_search_index,"item_id":self.web_search_item_id});
        self.emit("response.web_search_call.completed", completed);
        let done_item = build_responses_web_search_call_item(
            &self.web_search_item_id,
            &self.web_search_query,
            &self.web_search_queries,
            &self.web_search_sources,
        );
        let seq = self.next_seq();
        let done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":self.web_search_index,"item":done_item});
        self.emit("response.output_item.done", done);
        self.web_search_done = true;
    }

    // openReasoning closure
    fn open_reasoning(&mut self) {
        if self.reasoning_opened
            || self.reasoning_closed
            || (self.reasoning_buf.is_empty() && self.reasoning_enc.is_empty())
        {
            return;
        }
        self.finalize_web_search();
        self.reasoning_opened = true;
        self.reasoning_index = self.next_index;
        self.next_index += 1;
        self.reasoning_item_id = format!("rs_{}_{}", self.response_id, self.reasoning_index);
        let seq = self.next_seq();
        let enc = self.reasoning_encrypted_content();
        let item = json!({"type":"response.output_item.added","sequence_number":seq,"output_index":self.reasoning_index,"item":{"id":self.reasoning_item_id,"type":"reasoning","status":"in_progress","encrypted_content":enc,"summary":[]}});
        self.emit("response.output_item.added", item);
        let seq = self.next_seq();
        let part_added = json!({"type":"response.reasoning_summary_part.added","sequence_number":seq,"item_id":self.reasoning_item_id,"output_index":self.reasoning_index,"summary_index":0,"part":{"type":"summary_text","text":""}});
        self.emit("response.reasoning_summary_part.added", part_added);
        for delta in std::mem::take(&mut self.reasoning_pending_deltas) {
            let seq = self.next_seq();
            let msg = json!({"type":"response.reasoning_summary_text.delta","sequence_number":seq,"item_id":self.reasoning_item_id,"output_index":self.reasoning_index,"summary_index":0,"delta":delta});
            self.emit("response.reasoning_summary_text.delta", msg);
        }
    }

    // finalizeReasoning closure
    fn finalize_reasoning(&mut self) {
        self.open_reasoning();
        if !self.reasoning_opened || self.reasoning_closed {
            return;
        }
        let full = self.reasoning_buf.clone();
        let seq = self.next_seq();
        let text_done = json!({"type":"response.reasoning_summary_text.done","sequence_number":seq,"item_id":self.reasoning_item_id,"output_index":self.reasoning_index,"summary_index":0,"text":full});
        self.emit("response.reasoning_summary_text.done", text_done);
        let seq = self.next_seq();
        let part_done = json!({"type":"response.reasoning_summary_part.done","sequence_number":seq,"item_id":self.reasoning_item_id,"output_index":self.reasoning_index,"summary_index":0,"part":{"type":"summary_text","text":full}});
        self.emit("response.reasoning_summary_part.done", part_done);
        let seq = self.next_seq();
        let enc = self.reasoning_encrypted_content();
        let item_done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":self.reasoning_index,"item":{"id":self.reasoning_item_id,"type":"reasoning","encrypted_content":enc,"summary":[{"type":"summary_text","text":full}]}});
        self.emit("response.output_item.done", item_done);
        self.completed_reasoning.insert(
            self.reasoning_index,
            CompletedReasoning {
                id: self.reasoning_item_id.clone(),
                signature: enc,
                text: full,
            },
        );
        self.reasoning_closed = true;
    }

    // resetReasoning closure
    fn reset_reasoning(&mut self) {
        self.reasoning_opened = false;
        self.reasoning_closed = false;
        self.reasoning_index = 0;
        self.reasoning_item_id.clear();
        self.reasoning_enc.clear();
        self.reasoning_direction.clear();
        self.reasoning_target_kind.clear();
        self.reasoning_buf.clear();
        self.reasoning_pending_deltas.clear();
    }

    // openWebSearch closure
    fn open_web_search(&mut self) {
        if self.web_search_opened {
            return;
        }
        self.finalize_reasoning();
        self.web_search_opened = true;
        self.web_search_index = self.next_index;
        self.next_index += 1;
        self.web_search_item_id = format!(
            "ws_{}",
            self.response_id
                .strip_prefix("resp_")
                .unwrap_or(&self.response_id)
        );
        if self.web_search_query.is_empty() && !self.web_search_queries.is_empty() {
            self.web_search_query = self.web_search_queries[0].clone();
        }
        if self.web_search_query.is_empty() && self.req_json().is_some() {
            self.web_search_query = self.request_query();
        }
        let seq = self.next_seq();
        let added = json!({"type":"response.output_item.added","sequence_number":seq,"output_index":self.web_search_index,"item":{"id":self.web_search_item_id,"type":"web_search_call","status":"in_progress","action":{"type":"search","query":self.web_search_query}}});
        self.emit("response.output_item.added", added);
        let seq = self.next_seq();
        let searching = json!({"type":"response.web_search_call.searching","sequence_number":seq,"output_index":self.web_search_index,"item_id":self.web_search_item_id});
        self.emit("response.web_search_call.searching", searching);
    }

    fn open_message(&mut self) {
        self.msg_opened = true;
        self.msg_index = self.next_index;
        self.next_index += 1;
        self.current_msg_id = format!("msg_{}_{}", self.response_id, self.msg_index);
        let seq = self.next_seq();
        let item = json!({"type":"response.output_item.added","sequence_number":seq,"output_index":self.msg_index,"item":{"id":self.current_msg_id,"type":"message","status":"in_progress","content":[],"role":"assistant"}});
        self.emit("response.output_item.added", item);
        let seq = self.next_seq();
        let part_added = json!({"type":"response.content_part.added","sequence_number":seq,"item_id":self.current_msg_id,"output_index":self.msg_index,"content_index":0,"part":{"type":"output_text","annotations":[],"logprobs":[],"text":""}});
        self.emit("response.content_part.added", part_added);
        self.item_text_buf.clear();
        self.current_msg_rune_offset = 0;
    }

    fn emit_text_delta(&mut self, delta: &str) {
        let seq = self.next_seq();
        let msg = json!({"type":"response.output_text.delta","sequence_number":seq,"item_id":self.current_msg_id,"output_index":self.msg_index,"content_index":0,"delta":delta,"logprobs":[]});
        self.emit("response.output_text.delta", msg);
    }

    fn record_part_mapping(&mut self, part_index: i64, text: &str) {
        match self.part_mappings.last_mut() {
            Some(last) if last.part_index == part_index && last.message_index == self.msg_index => {
                last.part_text.push_str(text)
            }
            _ => self.part_mappings.push(GeminiPartMapping {
                part_index,
                message_index: self.msg_index,
                start_rune_in_msg: self.current_msg_rune_offset,
                part_text: text.to_string(),
            }),
        }
        self.current_msg_rune_offset += text.chars().count() as i64;
    }

    // flushWebSearchBufferedText closure
    fn flush_web_search_buffered_text(&mut self) {
        self.finalize_web_search();
        if self.web_search_buffered_deltas.is_empty() {
            return;
        }
        if self.msg_closed {
            self.msg_opened = false;
            self.msg_closed = false;
            self.item_text_buf.clear();
            self.current_msg_rune_offset = 0;
        }
        if !self.msg_opened {
            self.open_message();
        }
        for delta in std::mem::take(&mut self.web_search_buffered_deltas) {
            self.item_text_buf.push_str(&delta);
            self.emit_text_delta(&delta);
        }
        for (part_index, text) in std::mem::take(&mut self.web_search_buffered_parts) {
            self.record_part_mapping(part_index, &text);
        }
    }

    // emitNewCitationAnnotations closure
    fn emit_new_citation_annotations(
        &mut self,
        msg_index: i64,
        item_id: &str,
        annotations: &[Value],
    ) {
        let emitted = self
            .emitted_annotation_count
            .get(&msg_index)
            .copied()
            .unwrap_or(0);
        for (ann_idx, ann) in annotations.iter().enumerate().skip(emitted) {
            let seq = self.next_seq();
            let mut ev = json!({"type":"response.output_text.annotation.added","sequence_number":seq,"response_id":self.response_id,"item_id":item_id,"output_index":msg_index,"content_index":0,"annotation_index":ann_idx});
            set(&mut ev, "annotation", ann.clone());
            self.emit("response.output_text.annotation.added", ev);
        }
        if annotations.len() > emitted {
            self.emitted_annotation_count
                .insert(msg_index, annotations.len());
        }
    }

    // finalizeMessage closure
    fn finalize_message(&mut self) {
        self.finalize_web_search();
        if !self.web_search_buffered_deltas.is_empty() {
            self.flush_web_search_buffered_text();
        }
        if !self.msg_opened || self.msg_closed {
            return;
        }
        let full_text = self.item_text_buf.clone();
        let mut msg_citations: Vec<Value> = Vec::new();
        if let Some(gm) = &self.raw_grounding_metadata {
            let map = build_responses_url_citations_for_messages(
                gm,
                &self.part_mappings,
                std::slice::from_ref(&full_text),
            )
            .unwrap_or_default();
            msg_citations = map.get(&self.msg_index).cloned().unwrap_or_default();
            if msg_citations.is_empty() && self.completed_messages.is_empty() {
                if let Some(c0) = map.get(&0) {
                    if !c0.is_empty() {
                        msg_citations = c0.clone();
                    }
                }
            }
        }
        let (msg_index, msg_id) = (self.msg_index, self.current_msg_id.clone());
        self.emit_new_citation_annotations(msg_index, &msg_id, &msg_citations);
        let seq = self.next_seq();
        let done = json!({"type":"response.output_text.done","sequence_number":seq,"item_id":msg_id,"output_index":msg_index,"content_index":0,"text":full_text,"logprobs":[]});
        self.emit("response.output_text.done", done);
        let seq = self.next_seq();
        let mut part_done = json!({"type":"response.content_part.done","sequence_number":seq,"item_id":msg_id,"output_index":msg_index,"content_index":0,"part":{"type":"output_text","annotations":[],"logprobs":[],"text":full_text}});
        if !msg_citations.is_empty() {
            set_path(
                &mut part_done,
                "part.annotations",
                Value::Array(msg_citations.clone()),
            );
        }
        self.emit("response.content_part.done", part_done);
        let seq = self.next_seq();
        let mut fin = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":msg_index,"item":{"id":msg_id,"type":"message","status":"completed","content":[{"type":"output_text","annotations":[],"logprobs":[],"text":full_text}],"role":"assistant"}});
        if !msg_citations.is_empty() {
            set_path(
                &mut fin,
                "item.content.0.annotations",
                Value::Array(msg_citations.clone()),
            );
        }
        self.emit("response.output_item.done", fin);
        self.completed_messages.insert(
            msg_index,
            CompletedMessage {
                id: msg_id,
                text: full_text,
                annotations: msg_citations,
            },
        );
        self.msg_closed = true;
        self.current_msg_rune_offset = 0;
    }

    // emitLateCitations closure
    fn emit_late_citations(&mut self) {
        let Some(gm) = self.raw_grounding_metadata.clone() else {
            return;
        };
        if self.completed_messages.is_empty() {
            return;
        }
        let msg_texts: Vec<String> = self
            .completed_messages
            .values()
            .map(|m| m.text.clone())
            .collect();
        let Some(late_map) =
            build_responses_url_citations_for_messages(&gm, &self.part_mappings, &msg_texts)
        else {
            return;
        };
        let indexes: Vec<i64> = self.completed_messages.keys().copied().collect();
        let single = self.completed_messages.len() == 1;
        for idx in indexes {
            let mut late = late_map.get(&idx).cloned().unwrap_or_default();
            if late.is_empty() && single {
                if let Some(c0) = late_map.get(&0) {
                    if !c0.is_empty() {
                        late = c0.clone();
                    }
                }
            }
            let (id, existing) = {
                let m = &self.completed_messages[&idx];
                (m.id.clone(), m.annotations.clone())
            };
            let annotations = merge_citation_annotations(&existing, &late);
            self.emit_new_citation_annotations(idx, &id, &annotations);
            if !annotations.is_empty() {
                if let Some(m) = self.completed_messages.get_mut(&idx) {
                    m.annotations = annotations;
                }
            }
        }
    }

    // emitDetachedReasoning closure
    fn emit_detached_reasoning(&mut self, signature: &str, direction: &str, target: &str) {
        let signature = signature.trim().to_string();
        if signature.is_empty() || self.seen_reasoning_signatures.contains(&signature) {
            return;
        }
        self.finalize_reasoning();
        self.finalize_message();
        let idx = self.next_index;
        self.next_index += 1;
        let placement = if direction == CARRIER_PREVIOUS {
            "after"
        } else {
            "before"
        };
        let item_id = format!("rs_{}_detached_{}_{}", self.response_id, placement, idx);
        let carrier = encode_gemini_responses_carrier(&signature, direction, target);
        let seq = self.next_seq();
        let added = json!({"type":"response.output_item.added","sequence_number":seq,"output_index":idx,"item":{"id":item_id,"type":"reasoning","status":"in_progress","encrypted_content":carrier,"summary":[]}});
        self.emit("response.output_item.added", added);
        let seq = self.next_seq();
        let done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":idx,"item":{"id":item_id,"type":"reasoning","encrypted_content":carrier,"summary":[]}});
        self.emit("response.output_item.done", done);
        self.detached_reasoning.insert(
            idx,
            DetachedReasoning {
                id: item_id,
                signature: carrier,
            },
        );
        self.seen_reasoning_signatures.insert(signature);
    }

    // emitTrailingDetachedReasoning closure
    fn emit_trailing_detached_reasoning(&mut self, signature: &str) {
        match self.last_semantic_kind.as_str() {
            CARRIER_TEXT => {
                let signature = signature.trim().to_string();
                if signature.is_empty() || self.seen_reasoning_signatures.contains(&signature) {
                    return;
                }
                self.finalize_reasoning();
                self.finalize_message();
                if !self.msg_opened
                    || (self.reasoning_opened && self.reasoning_index > self.msg_index)
                {
                    self.emit_detached_reasoning(&signature, CARRIER_PREVIOUS, CARRIER_TEXT);
                    return;
                }
                let signatures = {
                    let entry = self
                        .hidden_text_signatures
                        .entry(self.current_msg_id.clone())
                        .or_default();
                    entry.push(signature.clone());
                    entry.clone()
                };
                if cache_gemini_responses_text_signatures(
                    &self.model_name,
                    &self.current_msg_id,
                    &self.item_text_buf,
                    &signatures,
                ) {
                    self.seen_reasoning_signatures.insert(signature);
                    return;
                }
                self.emit_detached_reasoning(&signature, CARRIER_PREVIOUS, CARRIER_TEXT);
            }
            CARRIER_FUNCTION => {
                self.emit_detached_reasoning(signature, CARRIER_PREVIOUS, CARRIER_FUNCTION)
            }
            _ => self.emit_detached_reasoning(signature, CARRIER_STANDALONE, CARRIER_ANY),
        }
    }

    // port of ConvertGeminiResponseToOpenAIResponses (gemini_openai-responses_response.go)
    fn convert(&mut self, raw_root: &Value) {
        let root = unwrap_gemini_response_root(raw_root).clone();

        if !self.started {
            self.response_id = gs(&root, "responseId");
            if self.response_id.is_empty() {
                self.response_id = synth_response_id();
            }
            if !self.response_id.starts_with("resp_") {
                self.response_id = format!("resp_{}", self.response_id);
            }
            if let Some(v) = root.get("createTime") {
                if let Some(t) = parse_rfc3339_unix(&gstr(Some(v))) {
                    self.created_at = t;
                }
            }
            if self.created_at == 0 {
                self.created_at = now_unix();
            }
            let seq = self.next_seq();
            let mut created = json!({"type":"response.created","sequence_number":seq,"response":{"id":self.response_id,"object":"response","created_at":self.created_at,"status":"in_progress","background":false,"error":null,"output":[]}});
            let mut request_model_name =
                request_model_name(self.original.as_ref(), self.request.as_ref());
            if request_model_name.is_empty() {
                request_model_name = self.model_name.clone();
            }
            if !request_model_name.is_empty() {
                set_path(&mut created, "response.model", json!(request_model_name));
            }
            self.emit("response.created", created);
            let seq = self.next_seq();
            let mut inprog = json!({"type":"response.in_progress","sequence_number":seq,"response":{"id":self.response_id,"object":"response","created_at":self.created_at,"status":"in_progress","output":[]}});
            if !request_model_name.is_empty() {
                set_path(&mut inprog, "response.model", json!(request_model_name));
            }
            self.emit("response.in_progress", inprog);
            self.started = true;
            self.next_index = 0;
            self.web_search_stream_mode = determine_web_search_stream_mode(
                &self.model_name,
                &request_model_name,
                self.original.as_ref(),
                self.request.as_ref(),
            );
        }

        // groundingMetadata
        if let Some(gm) = extract_grounding_metadata(&root) {
            self.raw_grounding_metadata =
                merge_grounding_metadata(self.raw_grounding_metadata.as_ref(), Some(gm));
            let merged = self.raw_grounding_metadata.clone();
            let queries = extract_grounding_queries(merged.as_ref());
            if !queries.is_empty() {
                if self.web_search_query.is_empty() {
                    self.web_search_query = queries[0].clone();
                }
                self.web_search_queries = queries;
            }
            let sources = extract_grounding_sources(merged.as_ref());
            if !sources.is_empty() {
                self.web_search_sources = sources;
            }
            if !self.web_search_opened && has_valid_web_grounding(merged.as_ref()) {
                self.open_web_search();
            }
            self.emit_late_citations();
        }

        if let Some(Value::Array(parts)) = gpath(&root, "candidates.0.content.parts") {
            for (part_idx_in_chunk, part) in parts.iter().enumerate() {
                self.convert_part(part_idx_in_chunk, part);
            }
        }

        let finish_reason = gs(&root, "candidates.0.finishReason");
        if gexists(&root, "candidates.0.finishReason") && !finish_reason.is_empty() {
            self.finish_response(&root);
        }
    }

    fn convert_part(&mut self, part_idx_in_chunk: usize, part: &Value) {
        let explicit_part_index = match part.get("partIndex").or_else(|| part.get("index")) {
            Some(p) => gint(Some(p)),
            None => -1,
        };
        let mut signature = gts(part, "thoughtSignature");
        if signature.is_empty() {
            signature = gts(part, "thought_signature");
        }
        let function_call = part.get("functionCall");
        let text = part.get("text");
        let text_str = gstr(text);
        let is_thought = gbool(part.get("thought"));

        let part_kind = if is_thought {
            "thought"
        } else if function_call.is_some() {
            "function"
        } else if text.is_some() {
            "text"
        } else {
            "unknown"
        };

        let current_part_index;
        if explicit_part_index >= 0 {
            current_part_index = explicit_part_index;
            self.current_logical_part_index = explicit_part_index;
            self.current_part_kind = part_kind.to_string();
            self.has_seen_first_part = true;
            self.text_part_run_active = part_kind == "text";
        } else {
            if !self.has_seen_first_part {
                self.has_seen_first_part = true;
                self.current_logical_part_index = 0;
                self.current_part_kind = part_kind.to_string();
                if part_kind == "text" {
                    self.text_part_run_active = true;
                }
            } else if part_idx_in_chunk > 0 || part_kind != self.current_part_kind {
                self.current_logical_part_index += 1;
                self.current_part_kind = part_kind.to_string();
                self.text_part_run_active = part_kind == "text";
            } else if part_kind == "function" {
                self.current_logical_part_index += 1;
                self.current_part_kind = part_kind.to_string();
                self.text_part_run_active = false;
            } else if part_kind == "text" && !self.text_part_run_active {
                self.current_logical_part_index += 1;
                self.current_part_kind = part_kind.to_string();
                self.text_part_run_active = true;
            }
            current_part_index = self.current_logical_part_index;
        }

        if function_call.is_some() && !self.pending_reasoning_signature.is_empty() {
            let pending = std::mem::take(&mut self.pending_reasoning_signature);
            if signature.is_empty() {
                self.emit_detached_reasoning(&pending, CARRIER_NEXT, CARRIER_FUNCTION);
            } else {
                self.emit_trailing_detached_reasoning(&pending);
            }
            self.pending_reasoning_signature.clear();
        }
        let reasoning_active = (self.reasoning_opened && !self.reasoning_closed)
            || (!self.reasoning_opened
                && (!self.reasoning_buf.is_empty() || !self.reasoning_enc.is_empty()));
        if !signature.is_empty() && !is_thought {
            if reasoning_active {
                if self.reasoning_enc.is_empty() || self.reasoning_enc == signature {
                    self.reasoning_enc = signature.clone();
                    if function_call.is_some() {
                        self.reasoning_direction = CARRIER_NEXT.to_string();
                        self.reasoning_target_kind = CARRIER_FUNCTION.to_string();
                    } else if text.is_some() && !text_str.is_empty() {
                        self.reasoning_direction = CARRIER_NEXT.to_string();
                        self.reasoning_target_kind = CARRIER_TEXT.to_string();
                    } else {
                        self.reasoning_direction = CARRIER_STANDALONE.to_string();
                        self.reasoning_target_kind = CARRIER_TEXT.to_string();
                    }
                    self.seen_reasoning_signatures.insert(signature.clone());
                } else {
                    self.finalize_reasoning();
                    if function_call.is_some() {
                        self.emit_detached_reasoning(&signature, CARRIER_NEXT, CARRIER_FUNCTION);
                    } else if !self.seen_reasoning_signatures.contains(&signature) {
                        self.pending_reasoning_signature = signature.clone();
                    }
                }
                if text.is_some() && text_str.is_empty() && function_call.is_none() {
                    self.finalize_reasoning();
                    return;
                }
            } else if function_call.is_some() {
                self.emit_detached_reasoning(&signature, CARRIER_NEXT, CARRIER_FUNCTION);
            } else if text.is_some() && !text_str.is_empty() {
                if !self.pending_reasoning_signature.is_empty()
                    && self.pending_reasoning_signature != signature
                {
                    let pending = std::mem::take(&mut self.pending_reasoning_signature);
                    self.emit_trailing_detached_reasoning(&pending);
                    self.pending_reasoning_signature.clear();
                }
                if !self.seen_reasoning_signatures.contains(&signature) {
                    self.pending_reasoning_signature = signature.clone();
                }
            } else if text.is_some() && text_str.is_empty() {
                if !self.pending_reasoning_signature.is_empty() {
                    let pending = std::mem::take(&mut self.pending_reasoning_signature);
                    if pending != signature {
                        self.emit_trailing_detached_reasoning(&pending);
                    }
                }
                if self.msg_opened
                    || !self.func_done.is_empty()
                    || !self.web_search_buffered_deltas.is_empty()
                {
                    self.emit_trailing_detached_reasoning(&signature);
                } else if !self.seen_reasoning_signatures.contains(&signature) {
                    self.pending_reasoning_signature = signature.clone();
                }
                return;
            }
        }

        // Reasoning text
        if is_thought {
            if !self.web_search_buffered_deltas.is_empty() {
                self.finalize_message();
            }
            if !self.pending_reasoning_signature.is_empty() && self.msg_opened && !self.msg_closed {
                let pending = std::mem::take(&mut self.pending_reasoning_signature);
                self.emit_trailing_detached_reasoning(&pending);
                self.pending_reasoning_signature.clear();
            }
            let mut incoming = String::new();
            if !signature.is_empty() && signature != GEMINI_RESPONSES_THOUGHT_SIGNATURE {
                if !self.pending_reasoning_signature.is_empty() {
                    let pending = std::mem::take(&mut self.pending_reasoning_signature);
                    if pending != signature {
                        self.emit_detached_reasoning(&pending, CARRIER_STANDALONE, CARRIER_ANY);
                    }
                    self.pending_reasoning_signature.clear();
                }
                incoming = signature.clone();
            } else if !self.pending_reasoning_signature.is_empty() {
                incoming = std::mem::take(&mut self.pending_reasoning_signature);
            }
            if self.reasoning_opened
                && !self.reasoning_closed
                && !incoming.is_empty()
                && !self.reasoning_enc.is_empty()
                && incoming != self.reasoning_enc
            {
                self.finalize_reasoning();
                self.reset_reasoning();
            }
            if self.reasoning_closed {
                self.finalize_message();
                self.reset_reasoning();
            } else if !self.reasoning_opened
                && self.reasoning_buf.is_empty()
                && self.msg_opened
                && !self.msg_closed
            {
                self.finalize_message();
            }
            if !incoming.is_empty() {
                self.reasoning_enc = incoming.clone();
                self.reasoning_direction = CARRIER_STANDALONE.to_string();
                self.reasoning_target_kind = CARRIER_TEXT.to_string();
                self.seen_reasoning_signatures.insert(incoming);
            }
            if text.is_some() && !text_str.is_empty() {
                self.last_semantic_kind = CARRIER_TEXT.to_string();
                self.reasoning_buf.push_str(&text_str);
                if self.reasoning_opened {
                    let seq = self.next_seq();
                    let msg = json!({"type":"response.reasoning_summary_text.delta","sequence_number":seq,"item_id":self.reasoning_item_id,"output_index":self.reasoning_index,"summary_index":0,"delta":text_str});
                    self.emit("response.reasoning_summary_text.delta", msg);
                } else {
                    self.reasoning_pending_deltas.push(text_str.clone());
                }
            }
            if !self.reasoning_opened && !self.reasoning_enc.is_empty() {
                self.open_reasoning();
            }
            return;
        }

        // Assistant visible text
        if text.is_some() && !text_str.is_empty() {
            if signature.is_empty()
                && !self.pending_reasoning_signature.is_empty()
                && ((self.msg_opened && !self.msg_closed)
                    || !self.web_search_buffered_deltas.is_empty())
            {
                let pending = std::mem::take(&mut self.pending_reasoning_signature);
                self.emit_trailing_detached_reasoning(&pending);
                self.pending_reasoning_signature.clear();
            }
            self.finalize_reasoning();
            if self.msg_closed {
                self.msg_opened = false;
                self.msg_closed = false;
                self.item_text_buf.clear();
                self.current_msg_rune_offset = 0;
            }
            if self.web_search_stream_mode && !self.web_search_done {
                self.last_semantic_kind = CARRIER_TEXT.to_string();
                self.web_search_buffered_deltas.push(text_str.clone());
                match self.web_search_buffered_parts.last_mut() {
                    Some((idx, buf)) if *idx == current_part_index => buf.push_str(&text_str),
                    _ => self
                        .web_search_buffered_parts
                        .push((current_part_index, text_str.clone())),
                }
                self.text_part_run_active = true;
                return;
            }
            if !self.msg_opened {
                self.open_message();
            }
            self.last_semantic_kind = CARRIER_TEXT.to_string();
            self.item_text_buf.push_str(&text_str);
            self.record_part_mapping(current_part_index, &text_str);
            self.emit_text_delta(&text_str);
            self.text_part_run_active = true;
            return;
        }

        // Function call
        if let Some(fc) = function_call {
            self.finalize_reasoning();
            self.finalize_web_search();
            if !self.web_search_buffered_deltas.is_empty() {
                self.flush_web_search_buffered_text();
            }
            self.finalize_message();
            self.last_semantic_kind = CARRIER_FUNCTION.to_string();

            let raw_name = gs(fc, "name");
            let identity = match self.tool_identity_map.get(&raw_name) {
                Some(i) => i.clone(),
                None => ResponsesToolIdentity {
                    name: restore_sanitized_tool_name(&self.sanitized_name_map, &raw_name),
                    ..Default::default()
                },
            };
            let (name, namespace, is_custom) = (identity.name, identity.namespace, identity.custom);

            let idx = self.next_index;
            self.next_index += 1;
            self.func_args_buf.entry(idx).or_default();
            if !matches!(self.func_call_ids.get(&idx), Some(c) if !c.is_empty()) {
                self.func_call_ids.insert(idx, synth_stream_call_id());
            }
            self.func_names.insert(idx, name.clone());
            self.func_namespaces.insert(idx, namespace.clone());
            self.func_custom.insert(idx, is_custom);

            let args_json = match fc.get("args") {
                Some(a) => a.to_string(),
                None => "{}".to_string(),
            };
            if self.func_args_buf[&idx].is_empty() && !args_json.is_empty() {
                self.func_args_buf.insert(idx, args_json.clone());
            }
            let call_id = self.func_call_ids[&idx].clone();

            if is_custom {
                let input = unwrap_responses_custom_tool_input(&args_json);
                self.func_input_buf.insert(idx, input.clone());
                let seq = self.next_seq();
                let mut item = json!({"type":"response.output_item.added","sequence_number":seq,"output_index":idx,"item":{"id":format!("ctc_{call_id}"),"type":"custom_tool_call","status":"in_progress","input":"","call_id":call_id,"name":""}});
                set_responses_tool_call_identity(&mut item, &name, &namespace, "item");
                self.emit("response.output_item.added", item);
                if !self.func_done.contains(&idx) {
                    let seq = self.next_seq();
                    let input_done = json!({"type":"response.custom_tool_call_input.done","sequence_number":seq,"item_id":format!("ctc_{call_id}"),"output_index":idx,"input":input});
                    self.emit("response.custom_tool_call_input.done", input_done);
                    let seq = self.next_seq();
                    let mut item_done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":idx,"item":{"id":format!("ctc_{call_id}"),"type":"custom_tool_call","status":"completed","input":input,"call_id":call_id,"name":""}});
                    set_responses_tool_call_identity(&mut item_done, &name, &namespace, "item");
                    self.emit("response.output_item.done", item_done);
                    self.func_done.insert(idx);
                }
            } else {
                let seq = self.next_seq();
                let mut item = json!({"type":"response.output_item.added","sequence_number":seq,"output_index":idx,"item":{"id":format!("fc_{call_id}"),"type":"function_call","status":"in_progress","arguments":"","call_id":call_id,"name":""}});
                set_responses_tool_call_identity(&mut item, &name, &namespace, "item");
                self.emit("response.output_item.added", item);
                if !args_json.is_empty() {
                    let seq = self.next_seq();
                    let ad = json!({"type":"response.function_call_arguments.delta","sequence_number":seq,"item_id":format!("fc_{call_id}"),"output_index":idx,"delta":args_json});
                    self.emit("response.function_call_arguments.delta", ad);
                }
                if !self.func_done.contains(&idx) {
                    let seq = self.next_seq();
                    let fc_done = json!({"type":"response.function_call_arguments.done","sequence_number":seq,"item_id":format!("fc_{call_id}"),"output_index":idx,"arguments":args_json});
                    self.emit("response.function_call_arguments.done", fc_done);
                    let seq = self.next_seq();
                    let mut item_done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":idx,"item":{"id":format!("fc_{call_id}"),"type":"function_call","status":"completed","arguments":args_json,"call_id":call_id,"name":""}});
                    set_responses_tool_call_identity(&mut item_done, &name, &namespace, "item");
                    self.emit("response.output_item.done", item_done);
                    self.func_done.insert(idx);
                }
            }
        }
    }

    // The finishReason branch of ConvertGeminiResponseToOpenAIResponses.
    fn finish_response(&mut self, root: &Value) {
        if !self.pending_reasoning_signature.is_empty() {
            let pending = std::mem::take(&mut self.pending_reasoning_signature);
            self.emit_trailing_detached_reasoning(&pending);
            self.pending_reasoning_signature.clear();
        }
        self.finalize_web_search();
        self.finalize_reasoning();
        self.finalize_message();

        // Close function calls (Gemini delivers each call whole, so these are
        // normally already done).
        let idxs: Vec<i64> = self.func_args_buf.keys().copied().collect();
        for idx in idxs {
            if self.func_done.contains(&idx) {
                continue;
            }
            let call_id = self.func_call_ids.get(&idx).cloned().unwrap_or_default();
            let name = self.func_names.get(&idx).cloned().unwrap_or_default();
            let namespace = self.func_namespaces.get(&idx).cloned().unwrap_or_default();
            if self.func_custom.get(&idx).copied().unwrap_or(false) {
                let input = self.func_input_buf.get(&idx).cloned().unwrap_or_default();
                let seq = self.next_seq();
                let input_done = json!({"type":"response.custom_tool_call_input.done","sequence_number":seq,"item_id":format!("ctc_{call_id}"),"output_index":idx,"input":input});
                self.emit("response.custom_tool_call_input.done", input_done);
                let seq = self.next_seq();
                let mut item_done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":idx,"item":{"id":format!("ctc_{call_id}"),"type":"custom_tool_call","status":"completed","input":input,"call_id":call_id,"name":""}});
                set_responses_tool_call_identity(&mut item_done, &name, &namespace, "item");
                self.emit("response.output_item.done", item_done);
            } else {
                let args = match self.func_args_buf.get(&idx) {
                    Some(b) if !b.is_empty() => b.clone(),
                    _ => "{}".to_string(),
                };
                let seq = self.next_seq();
                let fc_done = json!({"type":"response.function_call_arguments.done","sequence_number":seq,"item_id":format!("fc_{call_id}"),"output_index":idx,"arguments":args});
                self.emit("response.function_call_arguments.done", fc_done);
                let seq = self.next_seq();
                let mut item_done = json!({"type":"response.output_item.done","sequence_number":seq,"output_index":idx,"item":{"id":format!("fc_{call_id}"),"type":"function_call","status":"completed","arguments":args,"call_id":call_id,"name":""}});
                set_responses_tool_call_identity(&mut item_done, &name, &namespace, "item");
                self.emit("response.output_item.done", item_done);
            }
            self.func_done.insert(idx);
        }

        let seq = self.next_seq();
        let mut completed = json!({"type":"response.completed","sequence_number":seq,"response":{"id":self.response_id,"object":"response","created_at":self.created_at,"status":"completed","background":false,"error":null}});
        if let Some(req) = self.req_json().cloned() {
            echo_request_fields(&mut completed, "response", unwrap_request_root(&req));
        }

        self.emit_late_citations();

        let mut outputs: Vec<Value> = Vec::new();
        for idx in 0..self.next_index {
            if self.web_search_done && idx == self.web_search_index {
                outputs.push(build_responses_web_search_call_item(
                    &self.web_search_item_id,
                    &self.web_search_query,
                    &self.web_search_queries,
                    &self.web_search_sources,
                ));
                continue;
            }
            if let Some(r) = self.completed_reasoning.get(&idx) {
                outputs.push(json!({"id":r.id,"type":"reasoning","encrypted_content":r.signature,"summary":[{"type":"summary_text","text":r.text}]}));
                continue;
            }
            if let Some(m) = self.completed_messages.get(&idx) {
                let mut item = json!({"id":m.id,"type":"message","status":"completed","content":[{"type":"output_text","annotations":[],"logprobs":[],"text":m.text}],"role":"assistant"});
                if !m.annotations.is_empty() {
                    set_path(
                        &mut item,
                        "content.0.annotations",
                        Value::Array(m.annotations.clone()),
                    );
                }
                outputs.push(item);
                continue;
            }
            if let Some(d) = self.detached_reasoning.get(&idx) {
                outputs.push(json!({"id":d.id,"type":"reasoning","encrypted_content":d.signature,"summary":[]}));
                continue;
            }
            if let Some(call_id) = self.func_call_ids.get(&idx).filter(|c| !c.is_empty()) {
                let name = self.func_names.get(&idx).cloned().unwrap_or_default();
                let namespace = self.func_namespaces.get(&idx).cloned().unwrap_or_default();
                if self.func_custom.get(&idx).copied().unwrap_or(false) {
                    let input = self.func_input_buf.get(&idx).cloned().unwrap_or_default();
                    let mut item = json!({"id":format!("ctc_{call_id}"),"type":"custom_tool_call","status":"completed","input":input,"call_id":call_id,"name":""});
                    set_responses_tool_call_identity(&mut item, &name, &namespace, "");
                    outputs.push(item);
                } else {
                    let args = match self.func_args_buf.get(&idx) {
                        Some(b) if !b.is_empty() => b.clone(),
                        _ => "{}".to_string(),
                    };
                    let mut item = json!({"id":format!("fc_{call_id}"),"type":"function_call","status":"completed","arguments":args,"call_id":call_id,"name":""});
                    set_responses_tool_call_identity(&mut item, &name, &namespace, "");
                    outputs.push(item);
                }
            }
        }
        if !outputs.is_empty() {
            set_path(&mut completed, "response.output", Value::Array(outputs));
        }
        if self.web_search_done {
            set_path(
                &mut completed,
                "response.tool_usage.web_search.num_requests",
                json!(1),
            );
        }
        if let Some(um) = root.get("usageMetadata") {
            set_path(
                &mut completed,
                "response.usage.input_tokens",
                json!(gint(um.get("promptTokenCount"))),
            );
            set_path(
                &mut completed,
                "response.usage.input_tokens_details.cached_tokens",
                json!(gint(um.get("cachedContentTokenCount"))),
            );
            set_path(
                &mut completed,
                "response.usage.output_tokens",
                json!(gint(um.get("candidatesTokenCount")) + gint(um.get("thoughtsTokenCount"))),
            );
            set_path(
                &mut completed,
                "response.usage.output_tokens_details.reasoning_tokens",
                json!(gint(um.get("thoughtsTokenCount"))),
            );
            set_path(
                &mut completed,
                "response.usage.total_tokens",
                json!(gint(um.get("totalTokenCount"))),
            );
        }
        self.emit("response.completed", completed);
        self.completed = true;
    }
}

/// A complete upstream response → the client's Responses object.
pub fn translate_non_stream(upstream: &Value, original_request: &Value) -> Value {
    convert_gemini_response_to_openai_responses_non_stream(Some(original_request), None, upstream)
}

// port of ConvertGeminiResponseToOpenAIResponsesNonStream (gemini_openai-responses_response.go)
fn convert_gemini_response_to_openai_responses_non_stream(
    original: Option<&Value>,
    request: Option<&Value>,
    raw_root: &Value,
) -> Value {
    let root = unwrap_gemini_response_root(raw_root);
    let req_json = pick_request_json(original, request);
    let sanitized_name_map = sanitized_tool_name_map(original);
    let tool_identity_map = responses_tool_reverse_identity_map(req_json);

    let mut resp = json!({"id":"","object":"response","created_at":0,"status":"completed","background":false,"error":null,"incomplete_details":null});
    let mut id = gs(root, "responseId");
    if id.is_empty() {
        id = synth_response_id();
    }
    if !id.starts_with("resp_") {
        id = format!("resp_{id}");
    }
    set(&mut resp, "id", json!(id));
    let mut created_at = now_unix();
    if let Some(v) = root.get("createTime") {
        if let Some(t) = parse_rfc3339_unix(&gstr(Some(v))) {
            created_at = t;
        }
    }
    set(&mut resp, "created_at", json!(created_at));

    if let Some(req) = req_json {
        let req = unwrap_request_root(req);
        echo_request_fields(&mut resp, "", req);
        if req.get("model").is_none() {
            if let Some(v) = root.get("modelVersion") {
                set(&mut resp, "model", json!(gstr(Some(v))));
            }
        }
    } else if let Some(v) = root.get("modelVersion") {
        set(&mut resp, "model", json!(gstr(Some(v))));
    }

    struct ReasoningOut {
        text: String,
        signature: String,
        direction: String,
        target: String,
    }
    struct DetachedOut {
        signature: String,
        direction: &'static str,
        target: &'static str,
    }
    struct MessageOut {
        text: String,
        signatures: Vec<String>,
    }
    enum Order {
        Reasoning(usize),
        Message(usize),
        Function(usize),
        Detached(usize),
    }

    let mut reasoning_text = String::new();
    let mut reasoning_encrypted = String::new();
    let mut reasoning_direction = String::new();
    let mut reasoning_target = String::new();
    let mut reasoning_outputs: Vec<ReasoningOut> = Vec::new();
    let mut function_outputs: Vec<(Value, String)> = Vec::new();
    let mut message_outputs: Vec<MessageOut> = Vec::new();
    let mut detached_outputs: Vec<DetachedOut> = Vec::new();
    let mut order: Vec<Order> = Vec::new();
    let mut reasoning_output_signatures: HashSet<String> = HashSet::new();
    let mut current_message_text = String::new();
    let mut current_message_signatures: Vec<String> = Vec::new();
    let mut part_mappings: Vec<GeminiPartMapping> = Vec::new();
    let mut current_msg_rune_offset: i64 = 0;

    macro_rules! flush_reasoning {
        () => {
            if !reasoning_text.is_empty() || !reasoning_encrypted.is_empty() {
                let idx = reasoning_outputs.len();
                reasoning_outputs.push(ReasoningOut {
                    text: std::mem::take(&mut reasoning_text),
                    signature: reasoning_encrypted.clone(),
                    direction: std::mem::take(&mut reasoning_direction),
                    target: std::mem::take(&mut reasoning_target),
                });
                order.push(Order::Reasoning(idx));
                if !reasoning_encrypted.is_empty() {
                    reasoning_output_signatures.insert(std::mem::take(&mut reasoning_encrypted));
                }
            }
        };
    }
    macro_rules! flush_message {
        () => {
            if !current_message_text.is_empty() {
                let idx = message_outputs.len();
                message_outputs.push(MessageOut {
                    text: std::mem::take(&mut current_message_text),
                    signatures: std::mem::take(&mut current_message_signatures),
                });
                order.push(Order::Message(idx));
            }
        };
    }

    if let Some(Value::Array(parts)) = gpath(root, "candidates.0.content.parts") {
        for (key, p) in parts.iter().enumerate() {
            let part_idx = match p.get("partIndex").or_else(|| p.get("index")) {
                Some(v) => gint(Some(v)),
                None => key as i64,
            };
            let mut signature = gts(p, "thoughtSignature");
            if signature.is_empty() {
                signature = gts(p, "thought_signature");
            }
            if gbool(p.get("thought")) {
                flush_message!();
                current_msg_rune_offset = 0;
                if !signature.is_empty()
                    && !reasoning_encrypted.is_empty()
                    && signature != reasoning_encrypted
                {
                    flush_reasoning!();
                }
                if let Some(t) = p.get("text") {
                    reasoning_text.push_str(&gstr(Some(t)));
                }
                if !signature.is_empty() {
                    reasoning_encrypted = signature;
                    reasoning_direction = CARRIER_STANDALONE.to_string();
                    reasoning_target = CARRIER_TEXT.to_string();
                }
                continue;
            }
            let text = gs(p, "text");
            if p.get("text").is_some() && !text.is_empty() {
                let mut message_signature = String::new();
                if !signature.is_empty() {
                    if !reasoning_text.is_empty() && reasoning_encrypted.is_empty() {
                        reasoning_encrypted = signature.clone();
                        reasoning_direction = CARRIER_NEXT.to_string();
                        reasoning_target = CARRIER_TEXT.to_string();
                    } else {
                        message_signature = signature.clone();
                    }
                }
                flush_reasoning!();
                if !current_message_signatures.is_empty()
                    && (message_signature.is_empty()
                        || current_message_signatures.last() != Some(&message_signature))
                {
                    flush_message!();
                    current_msg_rune_offset = 0;
                }
                part_mappings.push(GeminiPartMapping {
                    part_index: part_idx,
                    message_index: message_outputs.len() as i64,
                    start_rune_in_msg: current_msg_rune_offset,
                    part_text: text.clone(),
                });
                current_msg_rune_offset += text.chars().count() as i64;
                current_message_text.push_str(&text);
                if !message_signature.is_empty()
                    && current_message_signatures.last() != Some(&message_signature)
                {
                    current_message_signatures.push(message_signature);
                }
                continue;
            }
            if let Some(fc) = p.get("functionCall") {
                if !reasoning_text.is_empty()
                    && reasoning_encrypted.is_empty()
                    && !signature.is_empty()
                {
                    reasoning_encrypted = std::mem::take(&mut signature);
                    reasoning_direction = CARRIER_NEXT.to_string();
                    reasoning_target = CARRIER_FUNCTION.to_string();
                }
                flush_reasoning!();
                flush_message!();
                current_msg_rune_offset = 0;

                let raw_name = gs(fc, "name");
                let identity = match tool_identity_map.get(&raw_name) {
                    Some(i) => i.clone(),
                    None => ResponsesToolIdentity {
                        name: restore_sanitized_tool_name(&sanitized_name_map, &raw_name),
                        ..Default::default()
                    },
                };
                let args_str = fc.get("args").map(Value::to_string).unwrap_or_default();
                let call_id = synth_non_stream_call_id();
                let mut item = if identity.custom {
                    json!({"id":format!("ctc_{call_id}"),"type":"custom_tool_call","status":"completed","input":unwrap_responses_custom_tool_input(&args_str),"call_id":call_id,"name":""})
                } else {
                    json!({"id":format!("fc_{call_id}"),"type":"function_call","status":"completed","arguments":args_str,"call_id":call_id,"name":""})
                };
                set_responses_tool_call_identity(
                    &mut item,
                    &identity.name,
                    &identity.namespace,
                    "",
                );
                let idx = function_outputs.len();
                function_outputs.push((item, signature));
                order.push(Order::Function(idx));
                continue;
            }
            if !signature.is_empty() {
                if !reasoning_text.is_empty() {
                    if reasoning_encrypted.is_empty() {
                        reasoning_encrypted = signature;
                        reasoning_direction = CARRIER_STANDALONE.to_string();
                        reasoning_target = CARRIER_TEXT.to_string();
                    } else if reasoning_encrypted != signature {
                        flush_reasoning!();
                        detached_outputs.push(DetachedOut {
                            signature,
                            direction: CARRIER_PREVIOUS,
                            target: CARRIER_TEXT,
                        });
                        order.push(Order::Detached(detached_outputs.len() - 1));
                    }
                } else if !current_message_text.is_empty() {
                    if current_message_signatures.is_empty() {
                        current_message_signatures.push(signature);
                    } else if current_message_signatures.last() != Some(&signature) {
                        flush_message!();
                        current_msg_rune_offset = 0;
                        detached_outputs.push(DetachedOut {
                            signature,
                            direction: CARRIER_PREVIOUS,
                            target: CARRIER_TEXT,
                        });
                        order.push(Order::Detached(detached_outputs.len() - 1));
                    }
                } else if !function_outputs.is_empty() {
                    detached_outputs.push(DetachedOut {
                        signature,
                        direction: CARRIER_PREVIOUS,
                        target: CARRIER_FUNCTION,
                    });
                    order.push(Order::Detached(detached_outputs.len() - 1));
                } else {
                    detached_outputs.push(DetachedOut {
                        signature,
                        direction: CARRIER_NEXT,
                        target: CARRIER_ANY,
                    });
                    order.push(Order::Detached(detached_outputs.len() - 1));
                }
            }
        }
    }
    flush_reasoning!();
    flush_message!();

    // Web search handling from groundingMetadata
    let gm = extract_grounding_metadata(root);
    let has_grounding = has_valid_web_grounding(gm);
    let mut ws_item = Value::Null;
    let mut message_citations: BTreeMap<i64, Vec<Value>> = BTreeMap::new();
    if has_grounding {
        let queries = extract_grounding_queries(gm);
        let mut query = queries.first().cloned().unwrap_or_default();
        if query.is_empty() {
            if let Some(r) = req_json {
                query = extract_responses_web_search_query(unwrap_request_root(r));
            }
        }
        let sources = extract_grounding_sources(gm);
        let ws_id = format!("ws_{}", id.strip_prefix("resp_").unwrap_or(&id));
        ws_item = build_responses_web_search_call_item(&ws_id, &query, &queries, &sources);
        let texts: Vec<String> = message_outputs.iter().map(|m| m.text.clone()).collect();
        if let Some(gm) = gm {
            message_citations =
                build_responses_url_citations_for_messages(gm, &part_mappings, &texts)
                    .unwrap_or_default();
        }
    }

    let rid = id.strip_prefix("resp_").unwrap_or(&id).to_string();
    let mut outputs: Vec<Value> = Vec::new();
    let mut detached_index = 0;
    let mut seen_detached: HashSet<String> = HashSet::new();
    let mut append_detached =
        |outputs: &mut Vec<Value>, signature: &str, direction: &str, target: &str| {
            if signature.is_empty() || !seen_detached.insert(signature.to_string()) {
                return;
            }
            let placement = if direction == CARRIER_PREVIOUS {
                "after"
            } else {
                "before"
            };
            outputs.push(json!({
                "id": format!("rs_{rid}_detached_{placement}_{detached_index}"),
                "type": "reasoning",
                "encrypted_content": encode_gemini_responses_carrier(signature, direction, target),
                "summary": [],
            }));
            detached_index += 1;
        };
    let mut ws_appended = false;
    for o in &order {
        match o {
            Order::Detached(i) => {
                let d = &detached_outputs[*i];
                if !reasoning_output_signatures.contains(&d.signature) {
                    append_detached(&mut outputs, &d.signature, d.direction, d.target);
                }
            }
            Order::Reasoning(i) => {
                let r = &reasoning_outputs[*i];
                let reasoning_id = if reasoning_outputs.len() > 1 {
                    format!("rs_{rid}_{i}")
                } else {
                    format!("rs_{rid}")
                };
                let mut enc = r.signature.clone();
                if !enc.is_empty() && !r.direction.is_empty() {
                    enc = encode_gemini_responses_carrier(&enc, &r.direction, &r.target);
                }
                let mut item =
                    json!({"id": reasoning_id, "type": "reasoning", "encrypted_content": enc});
                if !r.text.is_empty() {
                    set(
                        &mut item,
                        "summary",
                        json!([{"type": "summary_text", "text": r.text}]),
                    );
                }
                outputs.push(item);
            }
            Order::Message(i) => {
                if has_grounding && !ws_appended {
                    outputs.push(ws_item.clone());
                    ws_appended = true;
                }
                let m = &message_outputs[*i];
                for sig in &m.signatures {
                    if !reasoning_output_signatures.contains(sig) {
                        append_detached(&mut outputs, sig, CARRIER_NEXT, CARRIER_TEXT);
                    }
                }
                let mut item = json!({"id": format!("msg_{rid}_{i}"), "type": "message", "status": "completed", "content": [{"type": "output_text", "annotations": [], "logprobs": [], "text": m.text}], "role": "assistant"});
                if let Some(c) = message_citations.get(&(*i as i64)) {
                    if !c.is_empty() {
                        set_path(&mut item, "content.0.annotations", Value::Array(c.clone()));
                    }
                }
                outputs.push(item);
            }
            Order::Function(i) => {
                let (item, sig) = &function_outputs[*i];
                append_detached(&mut outputs, sig, CARRIER_NEXT, CARRIER_FUNCTION);
                outputs.push(item.clone());
            }
        }
    }
    if has_grounding && !ws_appended {
        outputs.push(ws_item);
    }
    if !outputs.is_empty() {
        set(&mut resp, "output", Value::Array(outputs));
    }
    if has_grounding {
        set_path(&mut resp, "tool_usage.web_search.num_requests", json!(1));
    }
    if let Some(um) = root.get("usageMetadata") {
        set_path(
            &mut resp,
            "usage.input_tokens",
            json!(gint(um.get("promptTokenCount"))),
        );
        set_path(
            &mut resp,
            "usage.input_tokens_details.cached_tokens",
            json!(gint(um.get("cachedContentTokenCount"))),
        );
        set_path(
            &mut resp,
            "usage.output_tokens",
            json!(gint(um.get("candidatesTokenCount")) + gint(um.get("thoughtsTokenCount"))),
        );
        if let Some(v) = um.get("thoughtsTokenCount") {
            set_path(
                &mut resp,
                "usage.output_tokens_details.reasoning_tokens",
                json!(gint(Some(v))),
            );
        }
        if let Some(v) = um.get("totalTokenCount") {
            set_path(&mut resp, "usage.total_tokens", json!(gint(Some(v))));
        }
    }
    resp
}

