    /// Calls `internal/util/responses_tools_test.go` and `sanitize_test.go`
    /// make to the tool helpers this pair uses, with Go's results (ed980be).
    #[test]
    fn golden_tool_helpers_match_go() {
        let mut failures = Vec::new();
        let mut n = 0;
        for (line_no, line) in TOOLS_GOLDEN.lines().enumerate() {
            let case: Value = serde_json::from_str(line).expect("golden line is JSON");
            n += 1;
            let got = match case["f"].as_str().unwrap() {
                "BuildGeminiFunctionDeclarations" => {
                    let d = build_gemini_function_declarations(&case["a"], true);
                    let forward: Map<String, Value> = d
                        .forward
                        .iter()
                        .map(|(k, v)| (k.clone(), json!(v)))
                        .collect();
                    let reverse: Map<String, Value> = d
                        .reverse
                        .iter()
                        .map(|(k, v)| (k.clone(), json!({"name": v.name, "namespace": v.namespace, "custom": v.custom})))
                        .collect();
                    json!({"decls": d.declarations, "forward": forward, "reverse": reverse})
                }
                "ConvertResponsesToolChoiceToGemini" => {
                    let forward: HashMap<String, String> = case["a"][1]
                        .as_object()
                        .map(|m| m.iter().map(|(k, v)| (k.clone(), gstr(Some(v)))).collect())
                        .unwrap_or_default();
                    convert_responses_tool_choice_to_gemini(&case["a"][0], &forward)
                        .unwrap_or(Value::Null)
                }
                "UnwrapResponsesCustomToolInput" => json!(unwrap_responses_custom_tool_input(
                    case["a"].as_str().unwrap()
                )),
                "SanitizeFunctionName" => {
                    json!(sanitize_function_name(case["a"].as_str().unwrap()))
                }
                other => panic!("unknown helper {other}"),
            };
            if got != case["out"] {
                failures.push(format!(
                    "line {}: {}\n got: {got}\nwant: {}",
                    line_no + 1,
                    case["f"],
                    case["out"]
                ));
            }
        }
        assert_eq!(n, 35, "tools golden count");
        assert!(
            failures.is_empty(),
            "{} mismatches:\n{}",
            failures.len(),
            failures.join("\n\n")
        );
    }

