    /// The schema inputs of `internal/util/gemini_schema_test.go`, each run
    /// through Go's `CleanJSONSchemaForGeminiJSONSchema` (commit ed980be).
    #[test]
    fn golden_schema_cleaner_matches_go() {
        let mut failures = Vec::new();
        let mut n = 0;
        for (line_no, line) in SCHEMA_GOLDEN.lines().enumerate() {
            let case: Value = serde_json::from_str(line).expect("golden line is JSON");
            n += 1;
            let got = clean_json_schema_for_gemini_json_schema(&case["in"]);
            if got != case["out"] {
                failures.push(format!(
                    "line {}\n in: {}\n got: {}\nwant: {}",
                    line_no + 1,
                    case["in"],
                    got,
                    case["out"]
                ));
            }
        }
        assert_eq!(n, 108, "schema golden count");
        assert!(
            failures.is_empty(),
            "{} mismatches:\n{}",
            failures.len(),
            failures.join("\n\n")
        );
    }

